import fs from 'node:fs'
function read(p) { return fs.readFileSync(p, 'utf8') }
function write(p, s) { fs.writeFileSync(p, s) }
function one(s, a, b, label) { const n = s.split(a).length - 1; if (n !== 1) throw new Error(`${label}: ${n} matches`); return s.replace(a, b) }

const newRadioFunction = "export function createWingmanRadio({ random = Math.random } = {}) {\n  let nextAllowedAt = -Infinity\n  let hasSaidAlone = false\n  const conversations = createWingmanRadioConversationManager({ random })\n\n  function scheduleNextNormalLine(now) {\n    nextAllowedAt = now + GLOBAL_COOLDOWN_MIN_MS + random() * (GLOBAL_COOLDOWN_MAX_MS - GLOBAL_COOLDOWN_MIN_MS)\n  }\n\n  function emit(pilotId, eventId, now, context = {}, force = false) {\n    if (!force && now < nextAllowedAt) return null\n    const pool = LINES[pilotId]?.[eventId]\n    if (!pool || pool.length === 0) return null\n    if (force) conversations.cancelPendingResponse('priority-interrupt')\n    const line = pool[Math.min(pool.length - 1, Math.floor(random() * pool.length))]\n    scheduleNextNormalLine(now)\n    conversations.openFromEvent({\n      openerPilotId: pilotId,\n      triggerEventId: eventId,\n      now,\n      activePilotIds: context.activePilotIds || [],\n      force,\n    })\n    return line\n  }\n\n  return {\n    trySpeak(pilotId, eventId, now = performance.now(), context = {}) {\n      return emit(pilotId, eventId, now, context, false)\n    },\n    forceSpeak(pilotId, eventId, now = performance.now(), context = {}) {\n      return emit(pilotId, eventId, now, context, true)\n    },\n    trySpeakAlone(pilotId, now = performance.now()) {\n      if (hasSaidAlone) return null\n      const line = emit(pilotId, 'alone', now, {}, false)\n      if (line) hasSaidAlone = true\n      return line\n    },\n    getLine(pilotId, eventId) {\n      const pool = LINES[pilotId]?.[eventId]\n      if (!pool || pool.length === 0) return null\n      return pool[Math.min(pool.length - 1, Math.floor(random() * pool.length))]\n    },\n    takeDueResponse(now = performance.now(), eligibleResponderIds = []) {\n      return conversations.takeDueResponse(now, eligibleResponderIds)\n    },\n    cancelPendingResponse(reason) {\n      return conversations.cancelPendingResponse(reason)\n    },\n    getConversationDebug() {\n      return conversations.getDebugSnapshot()\n    },\n    reset() {\n      nextAllowedAt = -Infinity\n      hasSaidAlone = false\n      conversations.reset()\n    },\n  }\n}\n"

let radio = read('src/combat/wingman-radio.js')
radio = "import { createWingmanRadioConversationManager } from './wingman-radio-callresponse.js'\nexport { CALL_RESPONSE_DELAY_MIN_MS, CALL_RESPONSE_DELAY_MAX_MS, CALL_RESPONSE_TTL_AFTER_DUE_MS, CALL_RESPONSE_THREAD_COOLDOWN_MS, classifyWingmanTransitionForRadio } from './wingman-radio-callresponse.js'\n\n" + radio
radio = one(radio, `    focus_ready: ['Locked and loaded!'],\n`, `    focus_ready: ['Locked and loaded!'],\n    state_critical: ["I'm taking a beating!", 'Systems are getting ugly!'],\n    state_emergency_return: ['Too far out — circling back.', 'Breaking off. Rejoining formation.'],\n    state_recovered: ["That's more like it.", "I'm back in business."],\n    action_interrupted: ['Tch. Move is off.', 'Abort that run.'],\n`, 'Falco lines')
radio = one(radio, `    focus_ready: ['Standing by.'],\n`, `    focus_ready: ['Standing by.'],\n    state_critical: ["Hull's in bad shape!", "I'm taking serious damage!"],\n    state_emergency_return: ["I'm outside the line — regrouping.", 'Returning to formation.'],\n    state_recovered: ['Systems stable again.', "I'm holding together."],\n    action_interrupted: ['Breaking off the maneuver.', 'Action canceled. Resetting.'],\n`, 'Peppy lines')
radio = one(radio, `    focus_ready: ['R-ready when you are!'],\n`, `    focus_ready: ['R-ready when you are!'],\n    state_critical: ["Uh-oh! My hull's critical!", 'I-I need some breathing room!'],\n    state_emergency_return: ["I'm too far out! Coming back!", 'Rejoining you now!'],\n    state_recovered: ['Whew! Systems are green again!', "Okay! I'm good!"],\n    action_interrupted: ['Ah! I have to abort!', 'Canceling that move!'],\n`, 'Slippy lines')
radio = one(radio, `    focus_ready: ['Awaiting your mark.', 'Command link ready.'],\n`, `    focus_ready: ['Awaiting your mark.', 'Command link ready.'],\n    state_critical: ['Hull integrity critical.', 'Damage threshold exceeded.'],\n    state_emergency_return: ['Formation distance exceeded. Correcting.', 'Returning to formation vector.'],\n    state_recovered: ['Integrity restored.', 'Systems stable. Resuming.'],\n    action_interrupted: ['Maneuver aborted.', 'Action interrupted. Reassessing.'],\n`, 'Miyu lines')
const marker = 'export function createWingmanRadio() {'
const idx = radio.indexOf(marker)
if (idx < 0) throw new Error('createWingmanRadio marker missing')
radio = radio.slice(0, idx) + newRadioFunction
write('src/combat/wingman-radio.js', radio)

let w = read('src/combat/wingmen.js')
w = one(w, `import { createWingmanRadio, ABILITY_EVENT_IDS } from './wingman-radio.js'`, `import { createWingmanRadio, ABILITY_EVENT_IDS, classifyWingmanTransitionForRadio } from './wingman-radio.js'`, 'radio import')
w = one(w, `  function buildRadioPayload(profile, text, eventId) {\n    return { pilotId: profile.id, name: profile.name, color: hexToCss(profile.accentColor), text, isAbility: ABILITY_EVENT_IDS.has(eventId) }\n  }\n  // Chama o dispatcher pra um evento de um piloto específico; devolve o payload pro HUD ou null\n  // (cooldown global ainda ativo, ou esse par piloto+evento não tem fala cadastrada).\n  function speak(profile, eventId) {\n    const text = wingmanRadio.trySpeak(profile.id, eventId)\n    return text ? buildRadioPayload(profile, text, eventId) : null\n  }\n`, `  function buildRadioPayload(profile, text, eventId, meta = {}) {\n    return { pilotId: profile.id, name: profile.name, color: hexToCss(profile.accentColor), text, isAbility: ABILITY_EVENT_IDS.has(eventId), eventId, ...meta }\n  }\n  function speak(profile, eventId) {\n    const text = wingmanRadio.trySpeak(profile.id, eventId, performance.now(), { activePilotIds: activeRadioPilotIds() })\n    return text ? buildRadioPayload(profile, text, eventId) : null\n  }\n`, 'speak integration')
w = one(w, `  const playerRollHistory = []\n\n  function authorityLabel(snapshot) {`, `  const playerRollHistory = []\n\n  function activeRadioPilotIds() {\n    return activeWingmen.map((wingman) => wingman.profile.id)\n  }\n\n  function authorityLabel(snapshot) {`, 'pilot ids helper')
w = one(w, `      aiValidator.logMechanic('wingman-transition', transition.decision, {\n        pilotId: wingman.profile.id, pilot: wingman.profile.name, region: transition.region, from,\n        requested: transition.requested, event: transition.event, source: transition.source, to,\n        reason: transition.reason, cooldownPolicy,\n      })\n    },\n    onInvariantFailure:`, `      aiValidator.logMechanic('wingman-transition', transition.decision, {\n        pilotId: wingman.profile.id, pilot: wingman.profile.name, region: transition.region, from,\n        requested: transition.requested, event: transition.event, source: transition.source, to,\n        reason: transition.reason, cooldownPolicy,\n      })\n      const semanticRadio = classifyWingmanTransitionForRadio(transition)\n      if (semanticRadio && (!pendingRadioMessage || semanticRadio.urgent)) {\n        const context = { activePilotIds: activeRadioPilotIds() }\n        const now = performance.now()\n        const text = semanticRadio.urgent\n          ? wingmanRadio.forceSpeak(wingman.profile.id, semanticRadio.eventId, now, context)\n          : wingmanRadio.trySpeak(wingman.profile.id, semanticRadio.eventId, now, context)\n        if (text) {\n          pendingRadioMessage = buildRadioPayload(wingman.profile, text, semanticRadio.eventId, { semanticTransition: true })\n          aiValidator.logMechanic('wingman-radio-semantic', semanticRadio.eventId, { pilotId: wingman.profile.id, source: transition.source, transitionEvent: transition.event, from, to, urgent: semanticRadio.urgent })\n        }\n      }\n    },\n    onInvariantFailure:`, 'semantic transitions')
w = one(w, `      if (readyQueue.length > 0) pendingRadioQueue = readyQueue`, `      if (readyQueue.length > 0) {\n        wingmanRadio.cancelPendingResponse('focus-command-queue')\n        pendingRadioQueue = readyQueue\n      }`, 'focus cancellation')
w = one(w, `  function clearSquadron() {\n    squadronFocusTargets = []\n`, `  function clearSquadron() {\n    squadronFocusTargets = []\n    wingmanRadio.reset()\n    pendingRadioMessage = null\n    pendingRadioQueue = null\n`, 'clear reset')
w = one(w, `    let radioQueue = pendingRadioQueue\n    pendingRadioQueue = null\n    // player_low_health dispara só na VIRADA (false→true), não every frame — um piloto aleatório\n`, `    let radioQueue = pendingRadioQueue\n    pendingRadioQueue = null\n    if (!radioMessage && !radioQueue) {\n      const eligibleResponderIds = activeWingmen.filter((wingman) => wingman.state !== 'damaged-passive' && wingman.state !== 'retreating').map((wingman) => wingman.profile.id)\n      const reply = wingmanRadio.takeDueResponse(performance.now(), eligibleResponderIds)\n      if (reply) {\n        const responder = activeWingmen.find((wingman) => wingman.profile.id === reply.pilotId)\n        if (responder) {\n          aiValidator.expect('Call & Response nunca usa o mesmo piloto como chamador e respondente', () => reply.pilotId !== reply.openerPilotId, { threadId: reply.threadId, openerPilotId: reply.openerPilotId, responderPilotId: reply.pilotId, triggerEventId: reply.triggerEventId })\n          aiValidator.logMechanic('wingman-radio-call-response', 'reply-delivered', { threadId: reply.threadId, openerPilotId: reply.openerPilotId, responderPilotId: reply.pilotId, triggerEventId: reply.triggerEventId })\n          telemetry.recordEvent(responder.profile.name, 'radio', 'Resposta de rádio para ' + reply.triggerEventId, { elapsed, threadId: reply.threadId, openerPilotId: reply.openerPilotId, triggerEventId: reply.triggerEventId })\n          radioMessage = buildRadioPayload(responder.profile, reply.text, 'radio_response', { threadId: reply.threadId, inReplyTo: reply.triggerEventId, openerPilotId: reply.openerPilotId })\n        }\n      }\n    }\n    // player_low_health dispara só na VIRADA (false→true), não every frame — um piloto aleatório\n`, 'response delivery')
w = one(w, `    if (retreating) {\n      const text = wingmanRadio.getLine(w.profile.id, 'retreat')\n      if (text) pendingRadioMessage = buildRadioPayload(w.profile, text, 'retreat')\n    }\n`, `    if (retreating) {\n      const text = wingmanRadio.forceSpeak(w.profile.id, 'retreat', performance.now(), { activePilotIds: activeRadioPilotIds() })\n      if (text) pendingRadioMessage = buildRadioPayload(w.profile, text, 'retreat')\n    }\n`, 'retreat priority')
write('src/combat/wingmen.js', w)
console.log('radio core migration applied')
